\begin{document}

\begin{abstract}
Let $K=\F_q$ and iterate the state-feedback commutator
$\Phi(A)=[\Diag(a_{11},\ldots,a_{nn}),A]$ on $\Mat_n(K)$, with the
standard ordered basis fixed.  The map satisfies $\Phi^2=0$, but its
one-step inverse problem is nonuniform.  We prove that a matrix $B$ is
reachable precisely when its diagonal is zero and the undirected support
graph of its off-diagonal entries is $q$-colourable.  More strongly, every
target fibre is an occupation-weighted proper-colouring sum.  This gives
closed graph sums for the image, a weak-composition formula for the kernel,
and the complete functional graph: one fixed root, explicit depth-one
leaves and branch vertices, and support-indexed depth-two leaves.  The zero
matrix uniquely maximizes the one-step fibre, and all later fibres and image
sets are immediate.  Classical matrix and group commutator theory and
Potts--chromatic partition functions are treated as prior owner regions;
the residual claim concerns only their exact conjunction for this literal
self-map.  External circulation remains on hold.
\end{abstract}

\maketitle

\section{Diagonal feedback and scope}

Fix a prime power $q$, put $K=\F_q$, and let
\begin{equation}\label{eq:map}
 \Delta(A)=\Diag(a_{11},\ldots,a_{nn}),\qquad
 \Phi:\Mat_n(K)\longrightarrow\Mat_n(K),\qquad
 \Phi(A)=[\Delta(A),A].
\end{equation}
The ordered basis is part of the definition: neither $\Delta$ nor $\Phi$ is
similarity invariant.  Entrywise,
\begin{equation}\label{eq:entry}
 \Phi(A)_{ij}=(a_{ii}-a_{jj})a_{ij}.
\end{equation}
Thus the diagonal is erased after one step.  The temporal clock is therefore
short, yet \eqref{eq:entry} leaves a nonconstant inverse multiplicity which
records how the input diagonal partitions the coordinate set.

This note makes a deliberately narrow claim.  Additive commutators with
prescribed diagonal behaviour belong to established matrix-commutator
theory \cite{Young2021,KadyrsizovaYerlanov2022}; images and fibres of
classical commutator word maps have their own literature
\cite{Baddeley1994,LarsenLu2021}.  Fixed-element triangular Engel equations
are treated by Bier \cite{Bier2013}.  In particular, the fixed-regular
unitriangular commutator system catalogued as P119 in the accompanying
programme---including its centralizer-coset fibres and filtration tree---is
assigned no contribution credit here.  Likewise, proper colourings and
Potts/Tutte partition functions are prior combinatorial mechanisms
\cite{Sokal2005}, and their labelled occupation enumerator is controlled by
Stanley's chromatic symmetric function \cite{Stanley1995}.  What remains is
the matrix-to-support reduction for every target of \eqref{eq:map} and the
rooted functional graph forced by it; no novelty or priority conclusion is
drawn from the bounded literature audit.

For a zero-diagonal $B\in\Mat_n(K)$, let $G_B$ be the simple graph on
$[n]=\{1,\ldots,n\}$ in which
\begin{equation}\label{eq:support}
 \{i,j\}\in E(G_B)
 \quad\Longleftrightarrow\quad
 b_{ij}\ne0\ \text{ or }\ b_{ji}\ne0.
\end{equation}
For a colouring $c:[n]\to K$, write
\[
 n_\alpha(c)=|c^{-1}(\alpha)|,
 \qquad
 m(c)=\sum_{\alpha\in K}n_\alpha(c)\bigl(n_\alpha(c)-1\bigr).
\]
Here $m(c)$ counts ordered pairs of distinct vertices of equal colour.  For
a simple graph $G$ define the occupation-marked proper-colouring sum
\begin{equation}\label{eq:partition}
 \mathcal P_{G,q}(X;\boldsymbol z)
 =\sum_{c\in\Col_q(G)}
 X^{m(c)}\prod_{\alpha\in K}z_\alpha^{n_\alpha(c)},
\end{equation}
where $\Col_q(G)$ is the set of proper $K$-colourings of $G$.
This polynomial is not proposed as a new graph invariant.  In the standard
$q$-state spin form of the multivariate Potts partition function on $K_n$,
put
\[
 v_{ij}=\begin{cases}
 -1,&\{i,j\}\in E(G),\\
 X^2-1,&\{i,j\}\notin E(G).
 \end{cases}
\]
Then
\begin{equation}\label{eq:potts-owner}
 Z^{\rm Potts}_{K_n}\!\left(q,\{v_{ij}\}\right)
 =\sum_{c:[n]\to K}\prod_{i<j}
   \left(1+v_{ij}\mathbf1_{\{c_i=c_j\}}\right)
 =\mathcal P_{G,q}(X;\boldsymbol1).
\end{equation}
A monochromatic edge of $G$ has factor zero, while each monochromatic
nonedge has factor $X^2$; under properness there are $m(c)/2$ such unordered
pairs.  Also,
\[
 X_G(z_1,\ldots,z_q,0,\ldots)
 =\sum_{c\in\Col_q(G)}\prod_{i=1}^n z_{c_i}
\]
is the $q$-variable truncation of Stanley's chromatic symmetric function.
The marked polynomial \eqref{eq:partition} is its deterministic
coefficientwise transform multiplying occupation $\boldsymbol r$ by
$X^{\sum_\alpha r_\alpha(r_\alpha-1)}$.  Both graph-polynomial identities
and their specializations receive zero contribution credit.

\section{Support colourings and every-target fibres}

\begin{theorem}[complete one-step fibre]\label{thm:fibre}
For every $B\in\Mat_n(K)$,
\begin{equation}\label{eq:fibre}
 |\Phi^{-1}(B)|=
 \begin{cases}
  \mathcal P_{G_B,q}(q;\boldsymbol 1),&\operatorname{diag}(B)=0,\\
  0,&\operatorname{diag}(B)\ne0.
 \end{cases}
\end{equation}
More precisely, for every occupation vector
$\boldsymbol r=(r_\alpha)_{\alpha\in K}$, the number of sources in the
fibre with $|\{i:a_{ii}=\alpha\}|=r_\alpha$ is the coefficient of
$\boldsymbol z^{\boldsymbol r}$ in
$\mathcal P_{G_B,q}(q;\boldsymbol z)$.  Consequently,
\begin{equation}\label{eq:imagecriterion}
 B\in\im\Phi
 \quad\Longleftrightarrow\quad
 \operatorname{diag}(B)=0\ \text{ and }\ \chi(G_B)\le q,
\end{equation}
and the fibre cardinality depends only on the undirected support $G_B$.
\end{theorem}

\begin{proof}
Every output has zero diagonal by \eqref{eq:entry}, proving the second line
of \eqref{eq:fibre}.  Suppose now that $B$ has zero diagonal and freeze the
prospective input diagonal as $c_i=a_{ii}$.  For each ordered pair $i\ne j$
we must solve
\begin{equation}\label{eq:scalar}
 (c_i-c_j)a_{ij}=b_{ij}.
\end{equation}
If $c_i\ne c_j$, there is exactly one solution.  If $c_i=c_j$, there are
$q$ solutions when $b_{ij}=0$ and none when $b_{ij}\ne0$.  Hence the
diagonal $c$ is admissible exactly when it is a proper colouring of $G_B$.
For such a colouring, precisely $m(c)$ ordered off-diagonal entries are
free, so it contributes $q^{m(c)}$ sources.  Summing over $c$ proves
\eqref{eq:fibre}; retaining the monomial in \eqref{eq:partition} proves the
marked assertion.  Positivity of every summand then gives
\eqref{eq:imagecriterion} and support-only dependence.
\end{proof}

Write $\kappa_{n,q}=|\Phi^{-1}(0)|$ and $I_{n,q}=|\im\Phi|$.

\begin{corollary}[kernel, image, and maximum]\label{cor:counts}
The zero matrix uniquely maximizes $|\Phi^{-1}(B)|$.  Moreover,
\begin{align}
 \kappa_{n,q}
 &=\sum_{\substack{(r_\alpha)_{\alpha\in K}\ge0\\
                    \sum_\alpha r_\alpha=n}}
   \binom{n}{(r_\alpha)_{\alpha\in K}}
   q^{\sum_\alpha r_\alpha(r_\alpha-1)},
   \label{eq:kappa}\\
 I_{n,q}
 &=\sum_{\substack{G\subseteq K_n\\\chi(G)\le q}}
   (q^2-1)^{|E(G)|}.
   \label{eq:image}
\end{align}
The graphs in \eqref{eq:image} are simple and labelled on $[n]$.
\end{corollary}

\begin{proof}
For $B=0$, the support graph is empty, so every colouring contributes; group
these colourings by their labelled occupation vector to obtain
\eqref{eq:kappa}.  If $B\ne0$ has zero diagonal, then $G_B$ contains an
edge.  Its proper colourings form a strict subset of all colourings, while
all weights $q^{m(c)}$ are positive.  If $B$ has nonzero diagonal, its fibre
is empty.  Thus zero is the unique maximum.

For \eqref{eq:image}, first choose the support $G$.  It occurs precisely when
$G$ is $q$-colourable.  On every edge $\{i,j\}$, the ordered pair
$(b_{ij},b_{ji})$ may be any nonzero vector in $K^2$, giving $q^2-1$
choices, independently across edges.  Nonedges force both entries to zero.
\end{proof}

At $X=q$, \eqref{eq:potts-owner} is exactly the unmarked target fibre in
\eqref{eq:fibre}, not merely a Potts analogy.  The retained step is instead
that the state-extracted diagonal turns every matrix inverse equation into
this standard support-colouring evaluation, simultaneously for every
target, and hence determines the functional graph below.

\section{The complete functional graph}

\begin{theorem}[clock, tree, and all-time fibres]\label{thm:graph}
The map satisfies $\Phi^2=0$.  Its functional graph is one rooted component
with the zero matrix as its only periodic point and with a loop at the root.
Its sharp height is $1$ for $n=1$ and $2$ for $n\ge2$.  The depth layers
have cardinalities
\begin{equation}\label{eq:depths}
 D_0=1,\qquad D_1=\kappa_{n,q}-1,\qquad
 D_2=q^{n^2}-\kappa_{n,q},
\end{equation}
where $D_2=0$ when $n=1$.

